) AS (
  VALUES 
    (542::BIGINT, 'Explica muy bien cada lab y puede ayudar al final del curso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '7793b6dec609670939ad862d4606b1b5d4c533dd323134ddb3eaeadd97794db7'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'En lo personal, a mí me parece un gran profesor. He encontrado malas calificaciones de personas en cursos más avanzados, pero yo tuve una muy buena experiencia en el mío. Es paciente y explica muy bien. Le pregunto como 5 cosas por clase y siempre me explica con buena actitud'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2026-04-29T00:00:00+00:00'::TIMESTAMPTZ, 'c822bc4e11aabb3a348e2dfebcffdceb1a87c297b7d7168b1afa43be7ce0390c'::TEXT, ARRAY[567]::BIGINT[]),
    (542::BIGINT, 'Buen profesor si te comprometes a ser buen estudiante desde el inicio, es muy estricto pero el curso en sí si haces todo bien siguiendo las indicaciones se pasa fácil, es muy serio por lo que es importante demostrar un respeto impecable si considera tenerlo de su lado'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2025-12-08T00:00:00+00:00'::TIMESTAMPTZ, '6e1333571374e7fa04de8f87c4e549da5fdc4de8cab75c7e3fca477e991aa681'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Pésimo profesor, en mi caso me llegó a gritar 2 veces y encima por quizá errores que uno comete, en vez de ayudarlo a uno, se altera cuestionándo porqué uno es así de malo. El profesor se despide del curso diciendo que todos somos una decepción. Así que resumidamente, pésima experiencia.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2025-10-02T00:00:00+00:00'::TIMESTAMPTZ, '5134aed2ff4a0f8db6453225e0ecd5a28b13431b7563ede1a3062f35d34965ef'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Peor profesor que existe si sos hombre, matricule con otros si puede, este semestre en mi grupo se quedaron 11 personas, se enoja muy fácil por preguntarle algo, no explica bien y califica duro (CUIDADO PLAGIO). Si usted se quiere como persona y quiere continuar en el TEC, matricule con otro profe.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '19b86a21f78a01440bd0eff490b91dd3aa39c40fb275a32ac6141d00090a3d0d'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Al ser un laboratorio siempre va a ser pesado, sin embargo, los quices que realiza sí son un poco tediosos. Cuando uno le pregunta algo se molesta un poco. Realizó un quiz extra para aumentar la nota.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '0153e7de48c1219508b43a463bfbfcfc37c3dfff205872492b31d8a15d2e1f9d'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'A pesar de calificar duro es un excelente profesor'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '9220733735176a0f6da5797ecf654c25b7842a8d2d6248695b1d49add96a9851'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Se altera con facilidad, aunque igual la bien las instrucciones de laboratorio; si tiene dudas, es probable que él hable un poco golpeado. El curso es pesado, lo mejor es obtener buenas calificaciones en quices e informes porque los exámenes algunas veces pueden ser complicados.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2024-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'd13e427a82ac50d7aa56ac6d6dea467d6588afb2ae4af1c5191ac1ec4138bc1c'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es un curso pesado, el profesor lo hace más pesado. Para los informes no califica tan duro, pero para los quiz sí. Es estricto'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-06-03T00:00:00+00:00'::TIMESTAMPTZ, '03c67129ee4ac4ff1a5f91419263764e1f4c268575b0e4b03b3c2fb152df6dcc'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Si sos hombre no lo recomiendo, cuando hice el examen me dijo necio por preguntaralgo, si una compañera le preguntaba algo a ella si le respondia con claridad, la tenia muy feo contra mi, y creo que era por ser hombre por que a varios compañeros les sucedia lo mismo, en cambio con las compañeras no.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-04-23T00:00:00+00:00'::TIMESTAMPTZ, 'ff0a8cf37ed7efffaf46c7bc0c993bf8439e192e8aeae0beae2d5657c9eca96d'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es un excelente profesor, es serio, pero se aprende mucho y se debe llevar la materia repasada antes de los laboratorios.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2023-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'b63e050a3caab8a65b296db0a69d112a4fde482d80277c0d9857c40da5c41679'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Super buen profe, ayuda si tiene alguna duda. La verdad hace el curso muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '7945bfda230933ef24485096d12d2808c58575a906f04594a7114d3feae8e691'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'El profe es algo terco como persona y como profe. Habla como si lo estuviera regañando siempre y como si el estudiante fuera tonto, pero es su forma de ser. Califica duro en el sentido de que baja puntos porque, por ejemplo, no le gustó cómo hizo un cuadro del informe. Déjelo como última opción.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd761c3937d5f0fa3d1aef504a96fa6e01e77c55c004694d1245df7436ffdd3c1'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es buena gente, da clases grabadas para ayudarse en los informes y ayuda mucho.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'dd4f68caaf4bbafb995af56a109b6f84509f3a8740a3df84bfec14ddc9bffed1'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es un buen profesor, califica un poco duro por lo que hay que estudiar antes de ir a sus clases, no revisa nada hasta final del semestre por lo que uno no sabe si al final va a pasar el curso'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2023-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'eaabe06b836931c6aeed2b65f3e79e38309732854d176ff25f869fd1bbe5bcec'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Innecesariamente repugnante, cuando se le mete el agua es empático pero del resto hasta un poco invivible. Pero el curso se pasa con que usted vaya al día con la materia y atiende las dudas, él dificulta un poco con sus actitudes pero nada del otro mundo, igual no lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-03-12T00:00:00+00:00'::TIMESTAMPTZ, '60c4b2381b97b567f0e9f46e7b426ce950f92c3ba31b6e33668c25b691f3fd84'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es sumamente atarantado, una persona realmente impaciente para todo, en el habla hasta cuesta entenderle de lo rápido y mal que habla, la verdad mi experiencia con este profesor ha sido de las peores de mi vida con un docente.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-12T00:00:00+00:00'::TIMESTAMPTZ, '898ad0e4e407af5dd6fb5724959fe07ca4207eea1d7006166686822879185657'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'De los emjores profes'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a815913b744f771cd42d6e05b0e12445420520fd0415dd0111f7bc9658da192f'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'El profe explica bien y los quices no son tan rudos. Califica normal, aunque las anotaciones que hace en los informes me resultaban algo confusas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '240492244c20516cba3786ee2fcee0a643f8b632cd993aee180468e446217c32'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es un profe serio, pero explica muy bien, los quices es el marco teórico de la práctica y los exámenes son similares a las práctica, así que hay que ir al día con la materia, lo recomiendo bastante.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'dc469d36928f9095cc3ff335889578f25340cb37deafea7b90c274ed88ce1a18'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Es muy serio y sus clases van al grano pero es un excelente profe. Los informes los califica masomenos duro pero luego uno les agarra el toque, solo hay que poner atención a detalles. Los exámenes y quices son duros. Se aprende bastante y explica muy bien.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, '6bc7fbf3a39b99d2a11db78300868bf0905598353a3f5b59f55a1add97a95819'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Muy buen profe, los informes no sentí que los calificara rudos , pero los exámenes sí. Explica bien ,es solo cuestión de ponerle'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2022-06-04T00:00:00+00:00'::TIMESTAMPTZ, '2d9b13bf307075669e845a6a86b4d74b1e4c7eb5e530a50f21084f7db3e8f1bf'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es bastante ordenado con las clases y sí es un toque estricto, pero se aprende mucho con él, los informes no sentí que los calificara muy duros, la verdad lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2022-05-24T00:00:00+00:00'::TIMESTAMPTZ, '774e08e5979790fc1053166f2cb6daa8fcf2e6599a752f708d330be0adca69ac'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Califica duro los informes, es recomendable utilizar un buen formato y referencias. El profesor es estricto pero de corazón noble, si usted demuestra interés en el curso el le va a ayudar,'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '69b5977f7f95d461f8c2e0ee3a99c6efcca321d2b0cd6849725b524728545f1a'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2021-09-02T00:00:00+00:00'::TIMESTAMPTZ, '5a6791471ce14fe932624ea29134ace82bf04e9645ff61a6ed5c0a9e1b684b3d'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Es un profesor estricto pero se aprende mucho, no se dejen engañar o se asusten por la apariencia seria y pregunten cualquier cosa.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-08-16T00:00:00+00:00'::TIMESTAMPTZ, '2b1687c2c3fcc92073a725b9b1a005853b1b74dc97429a6a81c4196cda580561'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Califica duro principalmente en los informes y exámenes. Los quices son sencillos y cuerdos con la materia. Es muy accesible a consultas. Califica Duro pero explica excelente y se preocupa por que usted entienda y de verdad aprenda'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, '057a4f3c9d09459d22ac926a087a847d63579808f8043b5064ef26522aaad84c'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Excelente profesor, lo único es que califica muy duro, pero después de ahí todo bien.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '8c8a83ddd93bd4167e051a823f421200ec2069dbab43c0b4de0e18eed297905b'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Tiene una asistente que te va a calificar RUDÍSIMO pero después de ahí todo bien, enseña bien. Hay quices semanales según la práctica y son de acorde a lo enseñado entonces bien. HAGAN LOS INFORMES casi PERFECTOS, si no les calificará super mal.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c62d24c978be367c931d92b10d071a83a645c87d5194dae993dbe2d0d9a1d90e'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Excelente profe, califica durillo pero justo, explica excelente y siempre esta dispuesto a aclara dudas, es muy accesible. En virtual hace exámenes cortos en GAAP super fáciles, casi siempre son selección única o verdadero falso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-18T00:00:00+00:00'::TIMESTAMPTZ, 'b215426a1e62b436b2775b3e17e643aba149bf2b80e97c474a0676cea019ad2f'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es bueno, sin embargo es muy duro para calificar informes y los exámenes son muy muy duros; a veces redunda mucho y tiende a confundirse, hay que estudiar mucho. Es un poco grotesco para decir las cosas además es muy estricto.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Exámenes retadores']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'a3ec5da2a079cd979b81be5a17d7a96d17f67680ac29effa0050c8d2a3394cd9'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Buen profesor. Rudo calificando, pero se aprende bastante con él. Muy serio pero muy accesible. Lo particular de él es que llama a los hombres por el apellido y a las mujeres por el nombre (nota curiosa)'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'ce439d1ac08acc39acf6754b53516bb61bf174c1b833615b8c5dfc4ebbd8f827'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Es súper cosi, sabe un monton y explica súper bien, claro y fácil. Te da todo para que los quices, cuestionarios previos e informes los podas hacer y los tengas bueno. Califica suave los informes y ayuda montones en ellos. Llevar el curso con él se hace relajado para lo rudo de los lab virtuales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '1ee7bb1c906536541753cb7ac149a459d6831b2a873a67d5bf6df400771a67b3'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Si un lab virtual por si solo es difícil, el profe lo hace un poquito mas complicado, es buena gente y suele responder las dudas siempre, se nota que sabe un montón pero no sabe extornarlo muy bien, califica SUPER duro en los informes'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Deja trabajos largos']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, '32142fcbc5cedba35e5d99958e6a373a4205f2a0eb881a382f231ddac409b576'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Califica bastante rudo los informes y sus clases son muy cortas y aburridas.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2020-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'b7a00af2f8338d4bbdfd89d9cb06fad6aac570cfda17e68c2d484e1c37a5bff4'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'En froma virtual sin duda el curso se toma como que valiera 3 créditos, pues hay que dedicarle bastante tiempo. Hace exámenes cortos antes de dar la clase de retroalimentación, pero son sencillos, siempre son falso o verdadero, o selección única. Es bastante serio, pero aclara las dudas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2020-09-02T00:00:00+00:00'::TIMESTAMPTZ, '98bf2aaa095ddeb602c110623ed4234f029d09e1e65836f404e64e33521249d4'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'El curso virtual es muy estructurado entonces le deja poco por hacer al profesor, pero en los informes si calificaba fuerte y a veces los quices eran bastante dificiles. El curso iba desfasado con la teoría, entonces había que ser autodidacta para hacer los informes.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, '866190d5966d123ee19a9303952addab69af5f385590c7b5f1734e0b5f234628'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Los informes son rudillos y el profe se pule mucho revisandolos, pero es mas facil el curso de forma virtual, el intenta que realmente uno entienda bien las practicas'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'e11dfb2a028191ef424e2c123479f46bafb4832d3e48da45662ffd2476d6ff15'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Es demasiado estricto calificando los informes. En la modalidad virtual la materia se hace muy fácil por la gran cantidad de material que brindan para que uno entienda. Los experimentos los hacen grabados entonces la clase es completamente teórica.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '29eceff8cd010b3baa37b8580df1198ea08a6daefbe06b4a286f236f9ce76ecf'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Sabe muho de la materia pero se debe de prestar mucha atención ya que todo lo de las practicas lo dan previamente y lo de los cuestionarios esta en el folleto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '07075dbec10f00f5d9f6ca6f13130800a5225d2d61ad73b7115ed91f5e2be013'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Siempre anda enojado. Los quizes son rudos y califaca duro. Uno aprende pero hay que poner para pasar. Hace que el curso consuma mucho tiempo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2020-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'ec9b1cad442c6d7aac655a472dc26c57f59b28639b04426a7940309316ca87ce'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'El profe para efectos materia si explica bien, pero es demasiado estricto en todo el sentido de la palabra, y un poco odioso pero ya eso es parte de la personalidad y no se puede cambiar. En general bueno.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '66a4052485e7af0f0c0997aa2f50fbe902839b5996038ad79a2eb5c5c150fd84'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Recomendado. No es mala persona ni mal profesor. Hay que ponerle al curso porque califica tal y como se debe y no deja pasar nada. Solo sea disciplinado y no va a sentir el curso.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-15T00:00:00+00:00'::TIMESTAMPTZ, '8fef5619ae81b2879fe909a07d2e28fdc15f0e50c004896a89292cbcb6058943'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Parece malhumorado pero es buena gente. Explica claro. Califica MUY estricto, definitivamente hay que ponerle ganas a los informes. Demanda que los laboratorios se realicen en menos de 1 hora'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes']::TEXT[], '2019-07-15T00:00:00+00:00'::TIMESTAMPTZ, '8620974d6e0bfb96a75c2543a6d05ce1f7f33e495b9e6223b83236849acfde7a'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es un profesor muy neutral, difícil y aburrido, a veces parecía molesto, pero en realidad solo es así.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '775ac8dc1133cbea4b9d46f8d1e5e9ed099be9f07c310c67207080bf2381963f'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'El profesor es bueno, solo que califica muy duro y es muy serio, pero en alguna duda que uno tenga el se lo va a contestar.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2019-06-07T00:00:00+00:00'::TIMESTAMPTZ, '6d4f0ea935954a22d74f29cc21af5bcfcfea5c1f84fc6ad657fe5abd6eec220c'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Señor intenso, no le importa si los estudiantes entendieron bien el laboratorio. No sé le entiende casi nada. Muy malhumorado. Definitivamente no se lo recomendaría a nadie'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-05-23T00:00:00+00:00'::TIMESTAMPTZ, 'b2d07c0ac377013f34542bb9afec2394316cc3e92bbb4412f49cdf66d36cb85b'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Explica bien lo que hay que hacer en las pácticas, pero califica duro los informes. Es amargado pero en el fondo muy buena gente, lo ayuda mucho a uno.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2019-02-03T00:00:00+00:00'::TIMESTAMPTZ, '6300c8ae39e3459e8114de5d31f57b2a1ad4abebc9beb723e02aa3f3493eebbf'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es muy duro calificando informes, si no son de la manera que él los quiere le baja demasiados puntos. Dura mucho en explicar antes del lab asi que termina dando muy poco tiempo para hacer el informe'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2019-01-20T00:00:00+00:00'::TIMESTAMPTZ, '2c4e5f98b0a075023eba1a85a799a025d0214d1c7c6a9f3376671410863439e3'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Califica rudo los informe, los quices no son tan complejos. Su mayor punto a favor es que explica muy claro. Ponga interés y esfuerzo en el curso, el curso no se pasa solo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, '1a09bc2e5382eabca2e28ac5eef930ce9216dacc561685757efe67bc669d5705'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'A veces está de mal humor pero es buen profe.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '0bb7ac62e73232207d2110d8072f8d730c2e910e0bb2f75c8e1b71f9d28c6e0a'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Buen profe, no califica tan duro. Siempre está de mal humor y pensando si la vida tiene sentido.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ad8097bbe4e82f26b91a6e4cd0b0e4805ff4c43685a42017e44f4c74d582e6cc'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Nada fuera de lo normal, en clase hace lo necesario para explicar los temas, lo mismo en las demostraciones de laboratorio. Muy serio, el principal contra es su forma de calificar reportes; resta puntos y medios puntos si no se hace como a él le gusta (es mejor consultarle hasta el mínimo detalle).'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4c189a8bb403e7f51db20e5d5e0bbcbb33987ead1a69c7aa1c9a2cd3c69ed3ff'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'e0190bd109e581e2603384dddbc1bb18e5f7ef13c8e6360ff3576e0971c7caaf'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Buen profesor'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'e89dfc6336010d22a02b1b2812fd13ce63ab44a292e67a048637e7aa6529cfc2'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Califica demasiado duro, se aprende bastante, si quiere pasar debe tomarla como una materia de 3 créditos, hacer todo con calma y saberse bastante bien la materia. Si tiene la opción de matricularlo con otro hágalo.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'e34a0132550631d475bc2f58e2a05e9eed030221991f05affad80e6c1c305228'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es demasiado bueno explicando y se sale rápido del laboratorio. Califica un poco rudo, pero lo compensa con la calidad de las clases.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2018-06-09T00:00:00+00:00'::TIMESTAMPTZ, '943086dd32ceeb4c68863a18821be2ee09f87e74fb32ea471887ef58543d3e4c'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Explica muy bien, califica un poco rudo los informes y exámenes. Es cuestión de prepararse antes de la clase (bitácora, tablas de los informes hechos y llevar todo claro para los quices).'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2017-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'c9805d85ac16089f2885712f535d3ce26108f2425c3f568ae12c0213bd0f3563'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Califica super rudo y es muy estricto, si se aprende de verdad pero no espere una buena nota.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '287ac624fc94274dcad2a46d7d6d0ff51f29ad2be03b66f868657259d5e173ce'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'de9143cb1fbce34c3df2c7f0907db39ad259a90ac8bade52b980bac865de1e88'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '91ef69dbbfd05b578d3be955a43eb3acb36962c1c4e6ade6af77229179784a1d'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es muy buena gente, pero si califica rudillo, le gusta que las ideas sean de calidad. Pero se aprende demasiado'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '5526e553a2cd34efcc623854baec3826a0f74ec2185dd52e16ef5b2a5156bba3'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Excelente profesor, explica de la mejor forma, muy rudo para calificar en quices y exámenes y a la hora de trabajar, pero se aprende de verdad.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, '42be8ab65eac03964bca9903f38aa86f16eff11a85821d6ba244e845249b9fef'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Califica duro y es muy serio, pero se aprende bastante, si uno le pone desde el principio y es responsable le va bien'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'a160cd6aeda01ea404cb28321030e3becf8ab0e1dd4a11d09009660078e737eb'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '6113b76e34ef033ca0ab40673d36508a4ff19739e8aff1be6c8b6fad3458a8de'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Definitivamente te puede hacer pasar un mal rato ,exige demasiado para un lab de 1 cred Ademas ,estuvo a nada de llamarnos idiotas ,claramente el quiere que todos sean quimicos,pero somos estudiantes. Es estudiar solo ,aprender solo ,y ojala no le consulte nada porque se estresa el profe y RIP ud'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-11-27T00:00:00+00:00'::TIMESTAMPTZ, '64449099b34b5220d22bc4e3c04c93b879fdcad591579918d22292e06f6abf1d'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es cierto que es bastante estricto con los informes y exámenes, pero solo es de ponerle un poco. Los quices son fáciles. Bastante claro con la materia y con lo que se hace en el lab.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-26T00:00:00+00:00'::TIMESTAMPTZ, '3ffb617164ef1ba19758dcfbdf3b50495059b9125fa9b2b60b59c42de24ae921'::TEXT, ARRAY[567, 613, 1433]::BIGINT[]),
    (542::BIGINT, 'Buen profe, algo serio y estricto, pero realmente se pasa sin mucho problema.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, '8c936d1f3ba7381fea009806a20db985807e37fbfe0766710b18c2ff4c2e4919'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Es demasiado rudo para calificar, le baja puntos por cualquier cosa. Se pone grosero e irrespetuoso cuando a uno se le olvida traer algo. Si es muy buen estudiante no va a tener problemas.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'ba03b1dc305fa48c0dc533a29376a5db22e4b8b804d62a59c7d839298abbe99e'::TEXT, ARRAY[567, 1433]::BIGINT[]),
    (542::BIGINT, 'Es un poco extricto y precisado, pero es buen profe. Califica un poco duro pero le ayuda bastante. Lo recomiendo'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'e5ec397f6a41288137f5aed3a36dbeaa1229df3275c751758d0d2ae4470ea77a'::TEXT, ARRAY[567, 1433]::BIGINT[]),
    (542::BIGINT, 'Califica bastante duro los informes y exámenes y es algo desesperado, pero da instrucciones muy claras y atiende dudas bastante bien'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '6e7bf9df67b8d2048459afc93cd665de37f78558270385e95289c856218b78d5'::TEXT, ARRAY[567, 1433]::BIGINT[]),
    (542::BIGINT, 'Califica duro los informes, no es buena idea tomar la clase con él si nunca ha estado en un laboratorio pues ayuda a los estudiantes pero de verdad necesitas experiencia para poder llevar la clase tranquilo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, '89e55d2eb0d7b17c6169bd763316e72118b4f5d5b45ee2ac439067a03590e1f9'::TEXT, ARRAY[567]::BIGINT[]),
    (542::BIGINT, 'Muy claro a la hora de dar la clase, quices simples y fáciles (si al menos se conoce sobre el tema), muy serio pero buen profesor'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'db489e11fccef2c7edd953f2f424675f52b79da5537fe2482097121cebe921de'::TEXT, ARRAY[567]::BIGINT[]),
    (542::BIGINT, 'Es un muy buen profe, pero si es muy serio y califica duro, hace quices faciles siempre y cuando se estudie Él ayuda si ve interes en el estudiante, y normalmente si maneja un poco la materia el ayuda.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '8d9a1c6cca95063c08fefc14135472cf1d5537af6af4941b69eb561eb638ba42'::TEXT, ARRAY[567, 1433]::BIGINT[]),
    (542::BIGINT, 'ES muy buen profe ayuda bastante y se preocupa porque las cosas le salgan a uno.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'dd6c5cc87312cba3d3b54508a217236ee0f3a291288f015a31739ac813374c69'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Aveces lo trata a uno mal pero por no hacer lo que debía. Muy fácil esta materia con él.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, '24e1ab28ee7c74e999375ec921c7e236c07c10561d6777bd072d01a228f5d0db'::TEXT, ARRAY[567, 1433]::BIGINT[]),
    (542::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, '5d55439fce245194f2985be2b4c764c615cdadab1cf4ac43d9a5ffc2a5195aff'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Como profe es muy bueno. Se aprende mucho, explica bien lo que se va a hacer. Tiene que llegar bien preparado a la clase, porque se enoja si le preguntan algo que ya se vio. Sin embargo, ayuda al que demuestra interés. Califica bastante duro.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-11T00:00:00+00:00'::TIMESTAMPTZ, '4002e86fada8018dad8d2b102743a53fc56766ed0183149448e43aff4a221c96'::TEXT, ARRAY[567, 1433]::BIGINT[]),
    (542::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'bd57685001fcc7cf16ac3778e4af8ee89ea3a5d86a1091da335b620d24404c4d'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Califica duro, baja puntos por cualquier cosa de los informes, hay que estar atento a la lección en todo momento sino le dice que se vaya de la clase, usted nunca va a ser amistad con él...'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-31T00:00:00+00:00'::TIMESTAMPTZ, '7accfff90d118fdd8520b44f4ca95a5985cee75daf591203e1b9e492e2ec51ff'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (542::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-31T00:00:00+00:00'::TIMESTAMPTZ, '2214eff390aab5bf9f7758c555c54a113a92ae3baf1f30c5124b7879a3ad73cc'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (542::BIGINT, 'Explica bien, califica muy duró, y tiene el problema de que califica x la cara del paciente y no por lo q se hace. Se vuelve pesado el curso xq busca el mínimo error para bajar puntos,'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2016-05-04T00:00:00+00:00'::TIMESTAMPTZ, '86a36c4757bca5b6b59a072ad50abd71b3c14d4e58673932362f849bdc43dbc1'::TEXT, ARRAY[1433]::BIGINT[]),
    (542::BIGINT, 'Estricto e impaciente, pero se aprende bien con él.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'deb2cc1aabeb3db56cb5bbb1411ec8a5abb4f3b94227570b2bd8456679875868'::TEXT, ARRAY[567, 1433]::BIGINT[]),
    (542::BIGINT, 'es mas malo que cagar sangre.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-08T00:00:00+00:00'::TIMESTAMPTZ, 'caa10f97d638c498ff77d78e72e7b99df44670abb23c33f26d3b7a8055cc36c6'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Excelente profesor!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'd59872c4b592ce875e16d6ac79b71937601cdb59958d0c6811bf69c66b755321'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'Es duro al calificar, pero explica muy bien y claro, se aprende bastante'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'c01c9d4112491eb6cccf76cd252cee531a1b78f9bc6a68ba92b25f6ed2cc490a'::TEXT, ARRAY[613]::BIGINT[]),
    (542::BIGINT, 'No es fácil pero explica muy bien. Califica duro, pero se aprende bastante'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-07T00:00:00+00:00'::TIMESTAMPTZ, '11a9ac2750125b2c8a8752516a5fcb2c843bcb65f9c6f30c959f6b5e98acbda7'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'Explica muy bien pero califica duro. Los quices son dificiles pero si se aprende.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2015-08-22T00:00:00+00:00'::TIMESTAMPTZ, 'd5b1350502cdaad2787038c7c46f3ad50b6fb1155ac6c7ee17f6e8b1cc936470'::TEXT, ARRAY[567, 1433]::BIGINT[]),
    (542::BIGINT, 'Sabe responder a todo lo que uno pueda preguntar de la clase. Si se da cuenta de que uno sabe lo que hace ayuda mucho. Prestando una bata o lentes, por ejemplo. Se aprende bien con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'f9a450c59f6ddfe82bb0bc11d62d22e2fd67bcc9f787bba867480606d1d5e2f1'::TEXT, ARRAY[567, 1433]::BIGINT[]),
    (542::BIGINT, 'Buen profesor, se aprende bastante, aunque califica duro y se enoja si se le pregunta algo que ya se vio hace mucho'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'c3a093b11ca9f08d7619dee943b479d3f1832e1ade48080e5b2d2fbeb5a63809'::TEXT, ARRAY[567, 1433]::BIGINT[]),
    (542::BIGINT, 'Muy buen profe, califica muy duro, pero se aprende mucho, atiende dudas, aunque a veces se molesta que le pregunten cosas muy basicas.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, '126c156df6af68c3a00c2aacd1f1ca600cb2e0ceed699a09c44039ea376d9fb1'::TEXT, ARRAY[567, 1433]::BIGINT[]),
    (542::BIGINT, 'Profe estricto pero con el que se aprende, si uno demuestra interés él es súper atento con las dudas, explica bien todo llo que se hace en el lab.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'dafd5428fbef28fd25f9f2c590321fa9a95a3256e0f3ee971a25d9f93ef40cb2'::TEXT, ARRAY[567]::BIGINT[]),
    (542::BIGINT, 'Es muy buen profesor, es un poco estricto, pero usted aprende muchísimo. Es calidad de persona. Siempre esta dispuesto a ayudar y aclarar las dudas que sean. Y si da puntos por reciclaje.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, '45fe1ec5b23004f24d9bc96964546390bd2d4ebc3cc1daa8f591e93230909fd1'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (542::BIGINT, 'Muy estricto calificando, los quices son duros, explica muy bien y aclara dudas. Se aprende pero cuesta mucho.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-08T00:00:00+00:00'::TIMESTAMPTZ, '403eaf01c1dcfcf22442761b317753c636ef02f45783b7e6f9d58db8e8bbb513'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (542::BIGINT, 'Es un profesor con el que realidad se aprende muy bien la materia, es exigente en el laboratorio y en los reportes. Super accesible a las dudas y en lo que se necesite. Muy recomendado!!'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, '5ed1dcc1c69e04c05ef8ca65ab97cf656afcfe74c2ed8ed9d0f506a7d9875ed7'::TEXT, ARRAY[613, 1433]::BIGINT[]),
    (542::BIGINT, 'El mae da una breve explicación de lo que se va a hacer en el lab. Hay que estudiar mucho para los quizes y aveces pregunta cosas de la teoría que no han visto. Tiene una actitud muy pedante y se enoja por cualquier cosa, no da puntos por reciclaje y un 70 en el examen es un milagro. No recomiendo'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '19e34bbb22de3e0472b90e7093ad4c1e59665dac651344ff9af0c9f186148623'::TEXT, ARRAY[567, 613, 1433]::BIGINT[]),
    (542::BIGINT, 'Es un profesor que no se le puede preguntar nada, es un pedante de primera clase. Aparte de eso, tiene que entender a la primera porque si pregunta algo que ya explicó se enoja, además no califica suave. El curso se puede pasar pero no es tan fácil.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '1e60980ec7b0b40e970b69429812d67f463e4040436c933a6be6ef2d5f9445c1'::TEXT, ARRAY[613, 567]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
